// host-registry r2 strict hash-pinned ADDITIVE generator: the QUALIFIED schema3 adapter candidate (SHA 07d02fca..., generated by
// lifecycle-schema3-adapter-review-r1 from r6 -> r3 8e666ed6 -> schema3 insertions, bundle bed9c196) -> a candidate with ONE more
// explicit pin profile, 'independent-host-registry-r1'. Insertions only (insertion-patch.mjs self-proof): every 07d02fca byte is
// retained in order, so with pins.profile absent, 'independent-r1' or 'independent-schema3-r1' every insertion is inert (each is
// guarded by HR, true ONLY for pins.profile === 'independent-host-registry-r1').
//
// HR implies S3: the whole schema-3 bundle/link/immutable/self-address/closure/admin verification runs unchanged. HR adds, inside the
// SAME pinned read: registry === hostOwnership (one address, the exact reviewed artifact runtime), registrySchema == 5,
// hostLifecycleSchema == 1, the feature id, and this host's canonical hostState/authority/reporterPolicy; new admission requires
// canonical Online. Nothing is submitted to the registry.
//
// The output must sit at network/deployment-chain-adapter.mjs of the composed tree, beside the schema3 r1 neighbours and
//   network/lifecycle-host-registry-profile.mjs                       (this task's src/network)
//   deploy/lifecycle/host-registry/EnclaveHostLifecycleRegistry.json  (reviewed Forge artifact e8690734...)
//   deploy/lifecycle/host-registry/EnclaveHostLifecycleRegistry.sol   (qualified source 68310acc...)
//
//   node generate-lifecycle-host-registry-adapter-candidate.mjs <abs 07d02fca adapter> <abs output file>
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { applyInsertions, writeInsertions } from
  '/home/steven/Documents/Codex/2026-10-18/wo/work/rpc-production-final-20261025/unified-funding-20261028/lifecycle-schema3-host-composition-r1/src/tools/insertion-patch.mjs';

export const SCHEMA3_ADAPTER_SHA256 = '07d02fca0fff2b4b59f7680ac0425c65b779aa61e13ae2b7205b7af4ee4443b2';
const MARKER = 'HOST_REGISTRY_PROFILE';

export const HOST_REGISTRY_EDITS = Object.freeze([
  { name: 'import',
    before: "import { SCHEMA3_PROFILE, isSchema3Profile, prepareSchema3, verifySchema3AtBlock, schema3Emergency, schema3Fields, schema3AdapterFields } from './lifecycle-schema3-profile.mjs';\n",
    after: "const SCHEMA3_BUNDLE_SHA256 = '",
    text: "// host-registry r2 (generated): explicit 'independent-host-registry-r1' = schema3 + ONE canonical EnclaveHostLifecycleRegistry as registry AND hostOwnership\n" +
      "import { HOST_REGISTRY_PROFILE, isHostRegistryProfile, prepareHostRegistry, verifyHostRegistryAtBlock, readHostLifecycle, hostLifecycleState, hostRegistryFields,\n" +
      "  hostRegistryAdapterFields } from './lifecycle-host-registry-profile.mjs';\n" },
  { name: 'profile-accept',
    before: '  if (pins.profile === SCHEMA3_PROFILE) return true;   // schema3 r1: also independent (address book = discovery) + schema3 checks/fields\n',
    after: '  if (pins.profile !== INDEPENDENT_PROFILE) throw',
    text: '  if (pins.profile === HOST_REGISTRY_PROFILE) return true;   // host-registry r2: also independent + schema3 + canonical host registry\n' },
  { name: 'hr-decl',
    before: '  // ACTUAL schema-3 ABIs of the hash-pinned bundle and statically proves every link/immutable/self-address pin (prepareSchema3).\n',
    after: '  const S3 = isSchema3Profile(pins)',
    text: "  const HR = isHostRegistryProfile(pins);   // host-registry r2: true ONLY for pins.profile === 'independent-host-registry-r1'; implies S3\n" },
  { name: 's3-includes-hr', before: '  const S3 = isSchema3Profile(pins)', after: ';\n  const S3P = S3 ? prepareSchema3', text: ' || HR' },
  { name: 'hr-prepare',
    before: '  const LIFECYCLE_ABI = S3 ? S3P.abi.lifecycle : R6_ABIS.LIFECYCLE_ABI, LEDGER_ABI = S3 ? S3P.abi.ledger : R6_ABIS.LEDGER_ABI;\n',
    after: '  getAddress(pins.payee);',
    text: '  const HRP = HR ? prepareHostRegistry(pins) : null;   // host-registry r2: exact artifact runtime/ABI; registry === hostOwnership (static)\n' },
  { name: 'hr-verify',
    before: '      if (S3) await verifySchema3AtBlock(S3P, client, number);\n',
    after: "      // the identity's FactoryPin[]",
    text: '      if (HR) await verifyHostRegistryAtBlock(HRP, client, number);   // host-registry r2: exact runtime/schema 5/lifecycle 1 at THIS block\n' },
  { name: 'hr-read',
    before: "        const hostAuthority = await call(C('hostOwnership'), HOST_OWNERSHIP_ABI, 'authority', [pins.host]);\n",
    after: "        // F4: production's exact appRef",
    text: "        const lifecycleHost = HR ? await readHostLifecycle(HRP, call, pins.host) : null;   // host-registry r2: canonical lifecycle, same block\n" },
  { name: 'hr-read-return', before: 'blockSec: Number(header.timestamp), retired, offline, lastEmergency', after: ' };\n      });', text: ', lifecycleHost' },
  { name: 'hr-state',
    before: '        pins.allowedMeasurements.includes(lower(v.hostRec.measurement));\n',
    after: '      const admitted = hostOk',
    text: '      const hr = HR ? hostLifecycleState(HRP, v) : null;   // host-registry r2: throws (state unknown) on any registry/authority inconsistency\n' },
  { name: 'hr-admitted', before: '      const admitted = hostOk && hostDenial === null && !adminChanged && !s3Pending', after: ';\n      const snapshot = {',
    text: ' && (!HR || hr.online === true)' },
  { name: 'hr-snapshot-fields',
    before: '        ...(S3 ? schema3Fields(v, s3) : {}),   // schema3 r1 only: schemas + emergency tuple; overrides profile/ledgerState/independence\n',
    after: '        policy: v.policy, budget:',
    text: '        ...(HR ? hostRegistryFields(HRP, hr) : {}),   // host-registry r2 only: overrides profile/hostOffline/independence\n' },
  { name: 'hr-adapter-object',
    before: '    ...(S3 ? schema3AdapterFields(S3P) : {}),   // schema3 r1\n',
    after: '    async read(id) {',
    text: '    ...(HR ? hostRegistryAdapterFields(HRP) : {}),   // host-registry r2\n' },
]);

/** (07d02fca adapter text) -> { source, sha256, baselineSha256, manifest }. Pure; self-proves restoration. */
export function generateHostRegistryCandidate(input) {
  return applyInsertions(input, { expectedSha256: SCHEMA3_ADAPTER_SHA256, edits: HOST_REGISTRY_EDITS, marker: MARKER,
    what: 'qualified schema3 deployment-chain-adapter candidate' });
}
export const writeHostRegistryCandidate = (input, output) => writeInsertions(input, output, generateHostRegistryCandidate, SCHEMA3_ADAPTER_SHA256);

if (process.argv[1] && fileURLToPath(import.meta.url) === fs.realpathSync(process.argv[1])) {
  const [input, output] = process.argv.slice(2);
  if (!input || !output) { console.error('usage: generate-lifecycle-host-registry-adapter-candidate.mjs <07d02fca adapter> <output>'); process.exit(2); }
  console.log(JSON.stringify(writeHostRegistryCandidate(input, output), null, 1));
}
